QString formatPaisa(pos::Money value) {
    const auto sign = value < 0 ? "-" : "";
    const auto absolute = value < 0 ? -value : value;
    return QString("%1%2.%3").arg(sign).arg(absolute / 100).arg(absolute % 100, 2, 10, QChar('0'));
}

