QWidget* MainWindow::makeCashManagement(){auto* page=new QWidget;auto* layout=new QVBoxLayout(page);layout->setContentsMargins(0,0,0,0);auto* title=new QLabel("Cash Management",page);title->setObjectName("pageTitle");layout->addWidget(title);auto* status=new QLabel(page);status->setObjectName("sectionTitle");auto* open=new QPushButton("Open shift",page);open->setObjectName("primary");auto* close=new QPushButton("Close shift",page);auto* actions=new QHBoxLayout;actions->addWidget(open);actions->addWidget(close);actions->addStretch();layout->addLayout(actions);layout->addWidget(status);layout->addStretch();const auto refresh=[this,status]{const auto id=pos::activeShiftId(*database_);status->setText(id.isEmpty()?"Till status: CLOSED":"Till status: OPEN\nShift: "+id);};refresh();connect(open,&QPushButton::clicked,this,[this,refresh]{bool ok=false;const auto opening=QInputDialog::getInt(this,"Open shift","Opening cash (paisa):",0,0,1000000000,1,&ok);if(!ok)return;try{pos::ShiftService(database_).open(opening);refresh();}catch(const std::exception& error){QMessageBox::critical(this,"Could not open shift",error.what());}});connect(close,&QPushButton::clicked,this,[this,refresh]{const auto id=pos::activeShiftId(*database_);if(id.isEmpty()){QMessageBox::information(this,"No open shift","Open a shift before closing the till.");return;}if(!authorizeSensitiveAction("close the shift"))return;bool ok=false;const auto counted=QInputDialog::getInt(this,"Close shift","Counted cash (paisa):",0,0,1000000000,1,&ok);if(!ok)return;try{const auto result=pos::ShiftService(database_).close(id,counted);refresh();QMessageBox::information(this,"Shift closed",QString("Expected: %1 paisa\nDifference: %2 paisa").arg(result.expected).arg(result.difference));}catch(const std::exception& error){QMessageBox::critical(this,"Could not close shift",error.what());}});return page;}
